import {
    DIAGRAM_FORMATTING_SCALE_MAXIMUM,
    DIAGRAM_FORMATTING_SCALE_MINIMUM,
    parseDiagramData,
    type DiagramConnectionKindFormatting,
    type DiagramData,
    type DiagramEdgeKind,
    type DiagramFormatting,
    type DiagramNodeRoleFormatting,
    type DiagramRole,
} from './diagram_data'

export const DIAGRAM_FORMATTING_SCALE_DEFAULT = 100
export const DIAGRAM_FORMATTING_SCALE_STEP = 10
export type DiagramScaleField = 'boxScalePercent' | 'fontScalePercent' | 'spacingScalePercent'
export type DiagramFormattingCategory = 'connectionKind' | 'nodeRole'

export function diagramScale(formatting: DiagramFormatting | undefined, field: DiagramScaleField) {
    return formatting?.[field] ?? DIAGRAM_FORMATTING_SCALE_DEFAULT
}

export function validateDiagramScale(value: number, field: DiagramScaleField) {
    if (!Number.isFinite(value) || value < DIAGRAM_FORMATTING_SCALE_MINIMUM || value > DIAGRAM_FORMATTING_SCALE_MAXIMUM) {
        throw new Error(
            `Malformed diagram data: formatting.${field} has number outside the `
            + `${DIAGRAM_FORMATTING_SCALE_MINIMUM}..${DIAGRAM_FORMATTING_SCALE_MAXIMUM} range`,
        )
    }
}

/** Validates formatting through shared parser and returns its canonical owned value. */
export function canonicalFormatting(diagram: DiagramData, formatting: DiagramFormatting): DiagramFormatting {
    const canonical = parseDiagramData(JSON.stringify({ ...diagram, formatting })).formatting
    if (!canonical) throw new Error('Malformed diagram data: formatting has invalid value')

    return canonical
}

export function withDiagramScale(
    diagram: DiagramData,
    field: DiagramScaleField,
    value: number,
) {
    validateDiagramScale(value, field)

    return canonicalFormatting(diagram, { ...diagram.formatting, [field]: value })
}

export function withNodeRoleFormatting(
    diagram: DiagramData,
    role: DiagramRole,
    value: DiagramNodeRoleFormatting,
) {
    return canonicalFormatting(diagram, {
        ...diagram.formatting,
        nodeRoles: { ...diagram.formatting?.nodeRoles, [role]: value },
    })
}

export function withConnectionKindFormatting(
    diagram: DiagramData,
    kind: DiagramEdgeKind,
    value: DiagramConnectionKindFormatting,
) {
    return canonicalFormatting(diagram, {
        ...diagram.formatting,
        connectionKinds: { ...diagram.formatting?.connectionKinds, [kind]: value },
    })
}

export function sameFormattingValue(left: unknown, right: unknown) {
    return JSON.stringify(left) === JSON.stringify(right)
}

import AddOutlined from '@mui/icons-material/AddOutlined'
import RemoveOutlined from '@mui/icons-material/RemoveOutlined'
import { Box, IconButton, Tooltip, Typography } from '@mui/material'
import {
    DIAGRAM_FORMATTING_SCALE_MAXIMUM, DIAGRAM_FORMATTING_SCALE_MINIMUM,
} from '../../services/diagrams/diagram_data'
import {
    DIAGRAM_FORMATTING_SCALE_STEP, type DiagramScaleField,
} from '../../services/diagrams/diagram_formatting'
import {
    type DiagramFormattingStore, useDiagramFormattingScale,
} from './use_diagram_formatting'

interface DiagramFormattingScaleStore extends DiagramFormattingStore {
    setFormattingScale(field: DiagramScaleField, value: number): void
}

/** One labelled, bounded percentage stepper for diagram-wide formatting. */
export function DiagramFormattingScaleControl({
    field,
    label,
    store,
    surface,
}: {
    field: DiagramScaleField
    label: string
    store: DiagramFormattingScaleStore
    surface: 'Current' | 'New'
}) {
    const value = useDiagramFormattingScale(field, store)
    const decrease = () => store.setFormattingScale(field, value - DIAGRAM_FORMATTING_SCALE_STEP)
    const increase = () => store.setFormattingScale(field, value + DIAGRAM_FORMATTING_SCALE_STEP)
    const accessibleLabel = `${surface} ${label}`

    return (
        <Box aria-label={accessibleLabel} sx={{ alignItems: 'center', display: 'flex', gap: 0.5 }}>
            <Typography color="text.secondary" variant="caption">{accessibleLabel}</Typography>
            <Tooltip title={`Decrease ${accessibleLabel}`}>
                <span>
                    <IconButton
                        aria-label={`Decrease ${accessibleLabel}`}
                        disabled={value <= DIAGRAM_FORMATTING_SCALE_MINIMUM}
                        onClick={decrease}
                        size="small"
                    >
                        <RemoveOutlined fontSize="small" />
                    </IconButton>
                </span>
            </Tooltip>
            <Typography aria-label={`${accessibleLabel} value`} sx={{ minWidth: 38, textAlign: 'center' }} variant="caption">
                {value}%
            </Typography>
            <Tooltip title={`Increase ${accessibleLabel}`}>
                <span>
                    <IconButton
                        aria-label={`Increase ${accessibleLabel}`}
                        disabled={value >= DIAGRAM_FORMATTING_SCALE_MAXIMUM}
                        onClick={increase}
                        size="small"
                    >
                        <AddOutlined fontSize="small" />
                    </IconButton>
                </span>
            </Tooltip>
        </Box>
    )
}

import { useCallback, useSyncExternalStore } from 'react'
import type {
    DiagramConnectionKindFormatting,
    DiagramEdgeKind,
    DiagramNodeRoleFormatting,
    DiagramRole,
} from '../../services/diagrams/diagram_data'
import type { DiagramScaleField } from '../../services/diagrams/diagram_formatting'

export interface DiagramFormattingStore {
    getConnectionKindFormattingSnapshot(kind: DiagramEdgeKind): DiagramConnectionKindFormatting | undefined
    getFormattingScaleSnapshot(field: DiagramScaleField): number
    getNodeRoleFormattingSnapshot(role: DiagramRole): DiagramNodeRoleFormatting | undefined
    subscribeConnectionKindFormatting(kind: DiagramEdgeKind, listener: () => void): () => void
    subscribeFormattingScale(field: DiagramScaleField, listener: () => void): () => void
    subscribeNodeRoleFormatting(role: DiagramRole, listener: () => void): () => void
}

const DEFAULT_DIAGRAM_FORMATTING_STORE: DiagramFormattingStore = {
    getConnectionKindFormattingSnapshot: () => undefined,
    getFormattingScaleSnapshot: () => 100,
    getNodeRoleFormattingSnapshot: () => undefined,
    subscribeConnectionKindFormatting: () => () => undefined,
    subscribeFormattingScale: () => () => undefined,
    subscribeNodeRoleFormatting: () => () => undefined,
}

export function useDiagramFormattingScale(field: DiagramScaleField, store?: DiagramFormattingStore) {
    const source = store ?? DEFAULT_DIAGRAM_FORMATTING_STORE
    const subscribe = useCallback((listener: () => void) => source.subscribeFormattingScale(field, listener), [field, source])
    const getSnapshot = useCallback(() => source.getFormattingScaleSnapshot(field), [field, source])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

export function useDiagramNodeRoleFormatting(role: DiagramRole, store?: DiagramFormattingStore) {
    const source = store ?? DEFAULT_DIAGRAM_FORMATTING_STORE
    const subscribe = useCallback((listener: () => void) => source.subscribeNodeRoleFormatting(role, listener), [role, source])
    const getSnapshot = useCallback(() => source.getNodeRoleFormattingSnapshot(role), [role, source])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

export function useDiagramConnectionKindFormatting(kind: DiagramEdgeKind, store?: DiagramFormattingStore) {
    const source = store ?? DEFAULT_DIAGRAM_FORMATTING_STORE
    const subscribe = useCallback(
        (listener: () => void) => source.subscribeConnectionKindFormatting(kind, listener),
        [kind, source],
    )
    const getSnapshot = useCallback(() => source.getConnectionKindFormattingSnapshot(kind), [kind, source])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

